window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1dd49fb617bda1db"]={"versions": [{"id": "FIG-1dd49fb617bda1db", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm ONE-SHOT_HW-TRIGGER_SINGLE-ACCESS</code>) des AUTOSAR ADC-Treibers (Microcontroller Abstraction Layer / MCAL). Das Diagramm spezifiziert das Zustandsmodell einer ADC-Kanalgruppe unter der statischen Konfiguration:</p>\n<ul class=\"fig-list\">\n<li>Konvertierungsmodus: One-Shot Conversion (<code>ADC_CONV_MODE_ONESHOT</code>)</li>\n<li>Triggerquelle: Hardware-Trigger (<code>ADC_TRIGG_SRC_HW</code>)</li>\n<li>Pufferzugriffsart: Single Access (<code>ADC_ACCESS_MODE_SINGLE</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Zustände:</strong></p>\n<ul class=\"fig-list\">\n<li>Startzustand (Initial State / schwarzer Kreis): Eintrittsknoten in die Zustandsmaschine.</li>\n<li><code>ADC_IDLE</code>: Gruppe ist ungetriggert / deaktiviert bzw. bereit zur Aktivierung des HW-Triggers.</li>\n<li><code>ADC_BUSY</code>: Hardware-Triggerung ist scharfgeschaltet bzw. Konvertierung aktiv.</li>\n<li><code>ADC_STREAM_COMPLETED</code>: Einzelner Wandlungsdurchlauf aller Gruppenkanäle abgeschlossen; Pufferergebnis steht zur Abholung bereit.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen / API-Funktionen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Adc_EnableHardwareTrigger</code>: Aktiviert die Hardware-Triggerquelle für die Kanalgruppe.</li>\n<li><code>Adc_DisableHardwareTrigger</code>: Deaktiviert die Hardware-Triggerung der Gruppe.</li>\n<li><code>Adc_ReadGroup</code>: Liest die zuletzt gewandelten Ergebnisse der Kanalgruppe aus.</li>\n<li><code>Adc_GetStreamLastPointer</code>: Liefert Zeiger auf die letzten gewandelten Abtastwerte im Puffer.</li>\n</ul>\n<p class=\"fig-p\"><strong>Interne Ereignisse:</strong></p>\n<ul class=\"fig-list\">\n<li><code>conversion of all group channels completed</code>: Signalisiert den Abschluss der Wandlung aller Kanäle der Gruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Übergang vom Initialknoten nach <code>ADC_IDLE</code>.</li>\n<li><strong>Aktivierung:</strong> Aus <code>ADC_IDLE</code> führt der Aufruf von <code>Adc_EnableHardwareTrigger</code> in den Zustand <code>ADC_BUSY</code>.</li>\n<li><strong>Deaktivierung:</strong> Aus <code>ADC_BUSY</code> kehrt die Zustandsmaschine bei Aufruf von <code>Adc_DisableHardwareTrigger</code> zurück nach <code>ADC_IDLE</code>.</li>\n<li><strong>Wandlungsabschluss:</strong> Mit Auftreten des internen Ereignisses <code>conversion of all group channels completed</code> wechselt der Zustand von <code>ADC_BUSY</code> nach <code>ADC_STREAM_COMPLETED</code>.</li>\n<li><strong>Ergebnisabruf & Reaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>ADC_STREAM_COMPLETED</code> führt der Aufruf von <code>Adc_GetStreamLastPointer</code> oder <code>Adc_ReadGroup</code> zurück in den Zustand <code>ADC_BUSY</code> (wobei die Hardware-Triggerung für einen neuen One-Shot-Durchlauf aktiv bleibt).</li>\n<li>Alternativ führt <code>Adc_DisableHardwareTrigger</code> direkt aus <code>ADC_STREAM_COMPLETED</code> zurück in den Zustand <code>ADC_IDLE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Selbstübergänge (Pufferlesezugriffe):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>ADC_IDLE</code> bewirken Aufrufe von <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> einen unkritischen Selbstübergang.</li>\n<li>In <code>ADC_BUSY</code> sind Aufrufe von <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> ebenfalls als Selbstübergänge zulässig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Bei Single Access und One-Shot mit HW-Trigger führt das Auslesen der Daten via <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> im Zustand <code>ADC_STREAM_COMPLETED</code> deterministisch zurück in den Zustand <code>ADC_BUSY</code>. Damit wird die Gruppe automatisch wieder scharfgeschaltet, um auf das nächste Hardware-Trigger-Ereignis zu warten.</li>\n<li>Soll nach einem Wandlungszyklus kein weiterer Durchlauf erfolgen, muss die Gruppe explizit über <code>Adc_DisableHardwareTrigger</code> gestoppt werden (Wechsel nach <code>ADC_IDLE</code>).</li>\n<li>Lesezugriffe (<code>Adc_ReadGroup</code>, <code>Adc_GetStreamLastPointer</code>) in den Zuständen <code>ADC_IDLE</code> und <code>ADC_BUSY</code> sind protokollarisch erlaubt (als Loopback-Transitionen modelliert), liefern jedoch abhängig von Spezifikationsdetails vorherige Werte oder Pufferstände gemäß Treiberstatus.</li>\n</ul>"}, {"id": "FIG-a3ec2a30f348419a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm ONE-SHOT_HW-TRIGGER_SINGLE-ACCESS</code>) des AUTOSAR ADC-Treibers (Microcontroller Abstraction Layer / MCAL). Das Diagramm spezifiziert das Zustandsmodell einer ADC-Kanalgruppe unter der statischen Konfiguration:</p>\n<ul class=\"fig-list\">\n<li>Konvertierungsmodus: One-Shot Conversion (<code>ADC_CONV_MODE_ONESHOT</code>)</li>\n<li>Triggerquelle: Hardware-Trigger (<code>ADC_TRIGG_SRC_HW</code>)</li>\n<li>Pufferzugriffsart: Single Access (<code>ADC_ACCESS_MODE_SINGLE</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Zustände:</strong></p>\n<ul class=\"fig-list\">\n<li>Startzustand (Initial State / schwarzer Kreis): Eintrittsknoten in die Zustandsmaschine.</li>\n<li><code>ADC_IDLE</code>: Gruppe ist ungetriggert / deaktiviert bzw. bereit zur Aktivierung des HW-Triggers.</li>\n<li><code>ADC_BUSY</code>: Hardware-Triggerung ist scharfgeschaltet bzw. Konvertierung aktiv.</li>\n<li><code>ADC_STREAM_COMPLETED</code>: Einzelner Wandlungsdurchlauf aller Gruppenkanäle abgeschlossen; Pufferergebnis steht zur Abholung bereit.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen / API-Funktionen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Adc_EnableHardwareTrigger</code>: Aktiviert die Hardware-Triggerquelle für die Kanalgruppe.</li>\n<li><code>Adc_DisableHardwareTrigger</code>: Deaktiviert die Hardware-Triggerung der Gruppe.</li>\n<li><code>Adc_ReadGroup</code>: Liest die zuletzt gewandelten Ergebnisse der Kanalgruppe aus.</li>\n<li><code>Adc_GetStreamLastPointer</code>: Liefert Zeiger auf die letzten gewandelten Abtastwerte im Puffer.</li>\n</ul>\n<p class=\"fig-p\"><strong>Interne Ereignisse:</strong></p>\n<ul class=\"fig-list\">\n<li><code>conversion of all group channels completed</code>: Signalisiert den Abschluss der Wandlung aller Kanäle der Gruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Übergang vom Initialknoten nach <code>ADC_IDLE</code>.</li>\n<li><strong>Aktivierung:</strong> Aus <code>ADC_IDLE</code> führt der Aufruf von <code>Adc_EnableHardwareTrigger</code> in den Zustand <code>ADC_BUSY</code>.</li>\n<li><strong>Deaktivierung:</strong> Aus <code>ADC_BUSY</code> kehrt die Zustandsmaschine bei Aufruf von <code>Adc_DisableHardwareTrigger</code> zurück nach <code>ADC_IDLE</code>.</li>\n<li><strong>Wandlungsabschluss:</strong> Mit Auftreten des internen Ereignisses <code>conversion of all group channels completed</code> wechselt der Zustand von <code>ADC_BUSY</code> nach <code>ADC_STREAM_COMPLETED</code>.</li>\n<li><strong>Ergebnisabruf & Reaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>ADC_STREAM_COMPLETED</code> führt der Aufruf von <code>Adc_GetStreamLastPointer</code> oder <code>Adc_ReadGroup</code> zurück in den Zustand <code>ADC_BUSY</code> (wobei die Hardware-Triggerung für einen neuen One-Shot-Durchlauf aktiv bleibt).</li>\n<li>Alternativ führt <code>Adc_DisableHardwareTrigger</code> direkt aus <code>ADC_STREAM_COMPLETED</code> zurück in den Zustand <code>ADC_IDLE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Selbstübergänge (Pufferlesezugriffe):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>ADC_IDLE</code> bewirken Aufrufe von <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> einen unkritischen Selbstübergang.</li>\n<li>In <code>ADC_BUSY</code> sind Aufrufe von <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> ebenfalls als Selbstübergänge zulässig.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Bei Single Access und One-Shot mit HW-Trigger führt das Auslesen der Daten via <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> im Zustand <code>ADC_STREAM_COMPLETED</code> deterministisch zurück in den Zustand <code>ADC_BUSY</code>. Damit wird die Gruppe automatisch wieder scharfgeschaltet, um auf das nächste Hardware-Trigger-Ereignis zu warten.</li>\n<li>Soll nach einem Wandlungszyklus kein weiterer Durchlauf erfolgen, muss die Gruppe explizit über <code>Adc_DisableHardwareTrigger</code> gestoppt werden (Wechsel nach <code>ADC_IDLE</code>).</li>\n<li>Lesezugriffe (<code>Adc_ReadGroup</code>, <code>Adc_GetStreamLastPointer</code>) in den Zuständen <code>ADC_IDLE</code> und <code>ADC_BUSY</code> sind protokollarisch erlaubt (als Loopback-Transitionen modelliert), liefern jedoch abhängig von Spezifikationsdetails vorherige Werte oder Pufferstände gemäß Treiberstatus.</li>\n</ul>"}], "trans": [{"from": "FIG-1dd49fb617bda1db", "to": "FIG-a3ec2a30f348419a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
